void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 resolution = max(iResolution.xy, vec2(1.0));
  vec2 uv = fragCoord / resolution;
  vec4 image = vrchSampleSource0(uv);
  vec2 aspect = vec2(resolution.x / resolution.y, 1.0);
  vec2 point = (uv - 0.5) * aspect;
  vec2 direction = vec2(cos(uParam_angle), sin(uParam_angle));
  float along = dot(point, direction);
  float across = dot(point, vec2(-direction.y, direction.x));
  float phase = iTime * uParam_speed;
  float bendA = sin(along * 2.3 + phase) * 0.055;
  float bendB = sin(along * 1.7 - phase * 0.83 + 2.1) * 0.07;
  float bendC = sin(along * 2.0 + phase * 0.61 + 4.4) * 0.045;
  float antialias = max(fwidth(across) * 1.5, 0.002);
  float bandA = 1.0 - smoothstep(uParam_width, uParam_width + antialias, abs(across + uParam_spacing + bendA));
  float bandB = 1.0 - smoothstep(uParam_width * 0.82, uParam_width * 0.82 + antialias, abs(across + bendB));
  float bandC = 1.0 - smoothstep(uParam_width * 1.12, uParam_width * 1.12 + antialias, abs(across - uParam_spacing + bendC));
  float mask = clamp(bandA * 0.68 + bandB * 0.52 + bandC * 0.62, 0.0, 1.0);
  vec3 treated = image.rgb + uParam_color.rgb * mask * uParam_brightness;
  fragColor = vec4(mix(image.rgb, treated, uParam_amount), image.a);
}
